-- 3) 頭文字ヒントを全語に自動生成（最終段 step=9）
--    ※読みから機械的に作れるので手入力させない。api/vocab_admin.php も
--      語を保存するたび同じ文言で作り直す（先生が消しても復活する）
INSERT INTO vocab_hints (word_id, step, hint_type, body)
SELECT word_id, 9, 'firstchar', CONCAT('頭文字は「', LEFT(yomi,1), '」')
FROM vocab_words;
-- example(step1)・synonym(step2) は先生が語ごとに vocab_hints へ追加
